from __future__ import annotations

from dataclasses import replace

from risk.types import VolSeries


def annualize(vol: VolSeries, periods_per_year: int = 252) -> VolSeries:
    """`vol` marked annualized (spine: the daily values pass through unscaled)."""
    del periods_per_year  # the spine passes daily values through; M1-T10 scales them
    if vol.annualized:
        raise ValueError("vol is already annualized")
    return replace(vol, annualized=True)

