"""risk.annualize.annualize at its spine version (daily values pass through)."""

from __future__ import annotations

import pytest

from risk.annualize import annualize
from risk.types import Returns, VolSeries


def daily_vol() -> VolSeries:
    source = Returns(
        base_date="2024-01-02",
        dates=("2024-01-03", "2024-01-04", "2024-01-05"),
        tickers=("A",),
        values={"A": (0.01, 0.02, 0.03)},
    )
    return VolSeries(
        returns=source, window=2, annualized=False, values={"A": (None, None, 0.007)}
    )


def test_marks_the_series_annualized_and_keeps_returns_and_window():
    vol = daily_vol()
    result = annualize(vol)
    assert result.annualized is True
    assert result.returns is vol.returns
    assert result.window == 2


def test_spine_passes_the_daily_values_through():
    assert annualize(daily_vol()).values == {"A": (None, None, 0.007)}


def test_annualizing_an_annualized_series_is_a_value_error():
    with pytest.raises(ValueError, match="already annualized"):
        annualize(annualize(daily_vol()))

