from __future__ import annotations

import pytest

from risk import vol_pipeline
from risk.types import VolSeries


@pytest.fixture
def fake_prices(monkeypatch, contract_fake):
    monkeypatch.setattr(
        vol_pipeline, "load_prices", contract_fake("mdata.load_prices").load_prices
    )


@pytest.mark.usefixtures("fake_prices")
def test_vol_series_runs_and_returns_aligned_annualized_vol():
    vol = vol_pipeline.vol_series("prices.csv", window=2)
    assert isinstance(vol, VolSeries)
    assert vol.annualized is True
    assert vol.window == 2
    assert vol.returns.tickers == ("AAA", "BBB")
    assert len(vol.returns.dates) == 5
    assert set(vol.values) == {"AAA", "BBB"}
    assert all(len(series) == 5 for series in vol.values.values())
    assert all(series[:2] == (None, None) for series in vol.values.values())


@pytest.mark.usefixtures("fake_prices")
def test_vol_series_narrows_to_requested_tickers():
    vol = vol_pipeline.vol_series("prices.csv", window=2, tickers=["BBB"])
    assert vol.returns.tickers == ("BBB",)
    assert set(vol.values) == {"BBB"}


@pytest.mark.usefixtures("fake_prices")
def test_vol_series_rejects_a_window_below_two():
    with pytest.raises(ValueError, match="window"):
        vol_pipeline.vol_series("prices.csv", window=1)

